// Parser webhook Pipedrive A04: dispara cuando un deal transiciona a lost
// con motivo de la familia 'No hay disponibilidad' (ids 357 ó 372).

const inp = $('Webhook A04 IN').first().json;
const body = inp.body || inp;
const meta = body.meta || {};
const action = meta.action || body.event_action || body.event || null;
const object = meta.object || body.event_object || null;
const cur = body.current || body.data || {};
const prev = body.previous || {};

// 1) Solo eventos de update sobre deals
if (!String(object || '').includes('deal')) {
  return [{ json: { ok: false, skip: true, reason: 'not_a_deal_event', object } }];
}
if (!String(action || '').match(/updated|change/i)) {
  return [{ json: { ok: false, skip: true, reason: 'not_an_update', action } }];
}

// 2) Trigger A04 = transición a lost con motivo de disponibilidad
// Trigger estricto: solo lost_reason 357 'INTERNA - No hay disponibilidad ... (OFERTA ACEPTADA)'
const A04_REASON_IDS = ['357', 357];
const isLostNow = String(cur.status || '').toLowerCase() === 'lost';
const wasLostBefore = String(prev.status || '').toLowerCase() === 'lost';
const reasonNow = cur.lost_reason_id || cur.lost_reason || null;
const reasonText = typeof cur.lost_reason === 'string' ? cur.lost_reason : '';
const reasonBefore = prev.lost_reason_id || prev.lost_reason || null;
const matchesA04 = A04_REASON_IDS.includes(reasonNow) ||
  /no hay disponibilidad.*oferta\s*aceptada/i.test(reasonText) ||
  /falta de disponibilidad/i.test(reasonText);

if (!isLostNow || !matchesA04) {
  return [{ json: { ok: false, skip: true, reason: 'not_a04_state', status: cur.status, lost_reason: cur.lost_reason } }];
}

// Dedup: solo procesar si es transición (no estaba ya en estado A04 antes)
const alreadyInA04State = wasLostBefore && (
  A04_REASON_IDS.includes(reasonBefore) ||
  /no hay disponibilidad.*oferta\s*aceptada/i.test(String(reasonBefore || ''))
);
if (alreadyInA04State) {
  return [{ json: { ok: false, skip: true, reason: 'already_in_a04_state', deal_id: cur.id } }];
}

// 3) Mapear campos custom Pipedrive → schema A04
const F = {
  assetType: '8a4171415b4177f4b7b15d0bdad9a202cf26db9b',
  assetEngine: '93586f4a594880d752f8406c62cab4174a2495ad',
  assetHeight: '9ab4702bc6ad498c9254eaeaad321002ecbb5500',
  assetWeight: '049ee75fcbcb04d99bc51c29f1067850ffd5ac0e',
  assetKVA: '66f2ac210435c4059f9452febc3109365ec092ee',
  assetExtra: '76853669b77be85d115aa66df5c97dd5cac87b9f',
  dateStart: 'b0bda5b24d686579053698d95f5054a9de9c3fcd',
  dateFinish: 'dcc1a242dace8fdf0db3da26ab9428f43ae441ab',
  zipcode: '2fd5cb02ee2858ee169c89cb1f94ab83f845173d',
  provincia: '98bda3ea4fc70a079f03240b1d7d3f176fc158f3',
  workAddress: '2184fde118dfc9382f1f996614fa28891f9a74c5',
  precioTrato: 'd0a90608ec6ae27b44b57bacd8163dc7223680f0',
  alquiladorOrig: '9a53d2ae313fbe8b092f0215219842cf64291ff7',
  cif: '2f94333d1a105a0af27ed6a8f1ea3656b553d7c3',
  razonSocial: '3ed9a86045d6202a652cddd85d270882690aa41b',
  rentDuration: '1b24939d619154af830ceb305c80a3ef329b415d',
  assetUse: 'cec043617eab0aa9a009d7feeb641ad62522cc4b'
};
const pick = (k) => cur[k] !== undefined && cur[k] !== '' ? cur[k] : null;

const dateStart = pick(F.dateStart);
const dateEnd = pick(F.dateFinish);
let durationDays = null;
if (dateStart && dateEnd) {
  const d1 = new Date(dateStart), d2 = new Date(dateEnd);
  if (!isNaN(d1) && !isNaN(d2)) durationDays = Math.max(1, Math.round((d2 - d1) / 86400000));
}
if (!durationDays && pick(F.rentDuration)) {
  const m = String(cur[F.rentDuration]).match(/(\d+)/);
  if (m) durationDays = parseInt(m[1], 10);
}

const precioTrato = parseFloat(pick(F.precioTrato)) || null;
const dailyRate = (precioTrato && durationDays) ? Math.round(precioTrato / durationDays) : null;

const person = cur.person_id || {};
const org = cur.org_id || {};
const personPhones = Array.isArray(person.phone) ? person.phone : [];
const personEmails = Array.isArray(person.email) ? person.email : [];

const payload = {
  event: 'deal.lost.availability',
  deal_id: String(cur.id || cur.deal_id || ''),
  pipedrive_url: cur.id ? `https://equipzilla.pipedrive.com/deal/${cur.id}` : null,
  client: {
    id: person.value ? `PD-${person.value}` : null,
    company_name: pick(F.razonSocial) || org.name || null,
    contact_name: person.name || null,
    phone: (personPhones[0] && personPhones[0].value) || null,
    email: (personEmails[0] && personEmails[0].value) || null,
    nif: pick(F.cif) || null
  },
  machine: {
    category: 'elevacion',
    subcategory: pick(F.assetType) || null,
    specifications: {
      tipo_motor: pick(F.assetEngine),
      altura_trabajo_m: pick(F.assetHeight),
      peso_kg: pick(F.assetWeight),
      potencia_kva: pick(F.assetKVA),
      extras: pick(F.assetExtra),
      uso_previsto: pick(F.assetUse)
    }
  },
  dates: { start: dateStart, end: dateEnd, duration_days: durationDays },
  location: {
    address: pick(F.workAddress),
    city: pick(F.provincia),
    postal_code: pick(F.zipcode),
    lat: null, lng: null
  },
  budget: { estimated_total_eur: precioTrato, daily_rate_target_eur: dailyRate },
  notes: [pick(F.assetExtra), pick(F.assetUse)].filter(Boolean).join(' · '),
  original_supplier_id: pick(F.alquiladorOrig) ? `PD-SUP-${cur[F.alquiladorOrig]}` : null,
  urgency: 'high',
  _raw_lost_reason: cur.lost_reason
};

const missing = [];
if (!payload.deal_id) missing.push('deal_id');
if (!payload.machine.subcategory) missing.push('machine.subcategory (assetType)');
if (!payload.dates.start) missing.push('dates.start (dateStart)');
if (!payload.location.postal_code && !payload.location.city) missing.push('location.postal_code|city');

if (missing.length) {
  return [{ json: { ok: false, error: 'incomplete_payload', missing, raw_current: cur, deal_id: payload.deal_id } }];
}
return [{ json: { ok: true, payload } }];

