const cfg = $('⚙️ Configuración').item.json;
const tier12Enabled = cfg.TIER12_ENABLED === true || cfg.TIER12_ENABLED === 'true';
const src = $('Validación anti-fugas').first().json;

// Feature flag: si Tier 1+2 está deshabilitado, devolvemos pool vacío para que
// el IF '¿Pool < 5?' siempre rute a la fase Tier 3 (cold outreach).
const items = tier12Enabled
  ? $input.all().map(i => i.json).filter(r => r && r.alquilador_id)
  : [];

return [{ json: {
  oferta_anonimizada: src.oferta_anonimizada,
  raw_payload: src.raw_payload,
  deal_id: src.deal_id,
  tier12_results: items,
  tier12_count: items.length,
  tier12_enabled: tier12Enabled
} }];

const places = ($json.results || []).slice(0, $('⚙️ Configuración').item.json.TIER3_MAX_RESULTS || 10);
const pool = $('Agrupar Tier 1+2').first().json;
const existingNames = new Set((pool.tier12_results || []).map(r => (r.nombre_comercial || '').toLowerCase().trim()));

const tier3 = places
  .filter(p => p.business_status !== 'CLOSED_PERMANENTLY')
  .filter(p => !existingNames.has((p.name || '').toLowerCase().trim()))
  .map(p => ({
    place_id: p.place_id,
    nombre_comercial: p.name,
    ciudad: ((p.formatted_address || '').split(',').slice(-2, -1)[0] || pool.oferta_anonimizada.location.city || '').trim(),
    lat: p.geometry && p.geometry.location && p.geometry.location.lat,
    lng: p.geometry && p.geometry.location && p.geometry.location.lng,
    rating: p.rating || null,
    formatted_address: p.formatted_address,
    tier: 'TIER_3',
    origen: 'cold_enrichment'
  }));

return tier3.map(item => ({ json: { ...item, _pool: pool } }));

const items = $input.all();
const pool = $('Agrupar Tier 1+2').first().json;
const cfg = $('⚙️ Configuración').item.json;

// Lista de "nuestros alquiladores" para excluir (no contactar)
const ownKeywords = String(cfg.OWN_SUPPLIERS_KEYWORDS || '')
  .split(',')
  .map(s => s.trim().toLowerCase())
  .filter(s => s.length >= 4); // min 4 chars para evitar falsos positivos

// Para keywords cortos (4-5 chars como 'gam') uso word boundary; para los demás substring
const normalizeMatch = (text) => String(text || '').toLowerCase().replace(/[^a-z0-9 ]/g, '');

const isOwnSupplier = (name, website) => {
  const nName = normalizeMatch(name);
  const nWeb = normalizeMatch(website || '');
  for (const kw of ownKeywords) {
    const k = normalizeMatch(kw);
    if (!k) continue;
    if (k.length <= 5) {
      // Word boundary match para evitar false-positive (gam dentro de igamba, etc.)
      const re = new RegExp('(^|[^a-z0-9])' + k + '([^a-z0-9]|$)');
      if (re.test(nName) || re.test(nWeb)) return kw;
    } else {
      if (nName.includes(k) || nWeb.includes(k)) return kw;
    }
  }
  return null;
};

const deriveEmail = (website) => {
  if (!website) return null;
  const m = String(website).match(/^https?:\/\/(?:www\.)?([a-z0-9.-]+\.(?:es|com|cat|net|org|eu))/i);
  if (!m) return null;
  const host = m[1].toLowerCase();
  if (host.includes('equipzilla')) return null;
  return `info@${host}`;
};

const enriched = items
  .map(it => {
    const r = (it.json && it.json.result) || {};
    const baseFromInput = $('Normalizar Tier 3').all().find(x => x.json.place_id === r.place_id);
    const base = (baseFromInput && baseFromInput.json) || {};
    const phone = r.international_phone_number || r.formatted_phone_number || null;
    const website = r.website || null;
    const derivedEmail = deriveEmail(website);
    const ownMatch = isOwnSupplier(r.name || base.nombre_comercial, website);
    return {
      alquilador_id: 'PROSPECT-' + (r.place_id || base.place_id || 'unknown'),
      nombre_comercial: r.name || base.nombre_comercial,
      ciudad: base.ciudad,
      whatsapp: phone ? phone.replace(/[^0-9+]/g, '') : null,
      website,
      email_comercial: derivedEmail,
      email_derivado: !!derivedEmail,
      formatted_address: r.formatted_address || base.formatted_address,
      tier: 'TIER_3',
      origen: 'cold_enrichment',
      raw_name: r.name,
      own_supplier_match: ownMatch
    };
  })
  .filter((r, i, arr) => arr.findIndex(x => x.email_comercial === r.email_comercial) === i)
  .filter(r => !/equipzilla/i.test(r.raw_name || ''))
  .filter(r => !r.own_supplier_match)  // excluir nuestros
  .filter(r => r.email_comercial);

const excluded = items
  .map(it => {
    const r = (it.json && it.json.result) || {};
    const baseFromInput = $('Normalizar Tier 3').all().find(x => x.json.place_id === r.place_id);
    const base = (baseFromInput && baseFromInput.json) || {};
    const own = isOwnSupplier(r.name || base.nombre_comercial, r.website);
    return own ? { name: r.name, match: own } : null;
  })
  .filter(Boolean);

return [{ json: {
  oferta_anonimizada: pool.oferta_anonimizada,
  raw_payload: pool.raw_payload,
  deal_id: pool.deal_id,
  tier12_results: pool.tier12_results,
  tier3_results_enriched: enriched,
  tier3_enriched_count: enriched.length,
  excluded_own_suppliers: excluded
} }];

// Marcador de alta. La implementación real Postgres se hace en producción.
// Aquí solo arrastramos el pool con los Tier 3 ya enriquecidos.
return [{ json: $json }];

const src = $json;
const tier12 = src.tier12_results || [];
const tier3 = (src.tier3_results_enriched || []).map(r => ({
  alquilador_id: r.alquilador_id,
  nombre_comercial: r.nombre_comercial,
  email_comercial: r.email_comercial,
  whatsapp: r.whatsapp,
  ciudad: r.ciudad,
  website: r.website,
  tier: 'TIER_3',
  origen: 'cold_enrichment'
}));

const seen = new Set();
const pool = [];
for (const a of [...tier12, ...tier3]) {
  const key = (a.alquilador_id || '') + '|' + (a.email_comercial || '') + '|' + (a.whatsapp || '');
  if (seen.has(key)) continue;
  seen.add(key);
  if (!a.email_comercial) continue;
  pool.push(a);
}

if (pool.length === 0) {
  return [{ json: {
    empty_pool: true,
    deal_id: src.deal_id,
    oferta_anonimizada: src.oferta_anonimizada,
    raw_payload: src.raw_payload,
    tier12_count: tier12.length,
    tier3_count: (src.tier3_results_enriched || []).length
  } }];
}

return pool.map(a => ({ json: {
  empty_pool: false,
  alquilador: a,
  oferta_anonimizada: src.oferta_anonimizada,
  deal_id: src.deal_id,
  raw_payload: src.raw_payload
} }));

const text = (($json.content && $json.content[0] && $json.content[0].text) || '').trim();
let parsed;
try {
  const clean = text.replace(/```json|```/g, '').trim();
  parsed = JSON.parse(clean);
} catch (e) {
