return [{ json: { opt_out_recorded: true, tracking_id: src.tracking_id, sender: src.sender } }];

// En producción: SELECT deal_id FROM outreach_log GROUP BY deal_id HAVING
//   MIN(timestamp_envio) < NOW() - INTERVAL '4 hours' AND
//   bool_or(estado_final='ganador') IS DISTINCT FROM true AND
//   bool_or(escalated) IS DISTINCT FROM true;
// Aquí lo dejamos como traza estructurada con datos del staticData del workflow.
const staticData = $getWorkflowStaticData('global');
const hours = $('⚙️ Configuración').item ? $('⚙️ Configuración').item.json.WATCHDOG_TIMEOUT_HOURS : 4;
const now = Date.now();
const windowMs = hours * 60 * 60 * 1000;
const escalated = [];
for (const [k, v] of Object.entries(staticData)) {
  if (!k.startsWith('reserva:')) continue;
  if (v && v.reserved_at && (now - v.reserved_at) > windowMs && !v.closed && !v.escalated) {
    v.escalated = true;
    escalated.push({ deal_id: k.split(':')[1], state: v });
  }
}
return escalated.length ? escalated.map(e => ({ json: e })) : [{ json: { _empty: true } }];

